// Renders `oxcruise --rules` (JSON) as docs/rules.md. Usage: node rules-md.mjs rules.json > docs/rules.md
import { readFileSync } from "node:fs";

const rules = JSON.parse(readFileSync(process.argv[2], "utf8"));
const byCategory = Map.groupBy(rules, (r) => r.category);
const order = ["correctness", "suspicious", "style", "restriction", "nursery"];

let out =
  "<!-- generated by `just rule-docs` from the declare_rule! doc comments; do not edit -->\n\n# Built-in rules\n\n";
// what a category does when the config does not mention it
const defaults = { correctness: "error", suspicious: "warn" };
const level = (category) => defaults[category] ?? "off";
out += "| Rule | Category | Default |\n|---|---|---|\n";
for (const r of rules)
  out += `| [\`${r.name}\`](#${r.name}) | ${r.category} | ${level(r.category)} |\n`;
for (const cat of order.filter((c) => byCategory.has(c))) {
  out += `\n## ${cat[0].toUpperCase()}${cat.slice(1)}\n`;
  for (const r of byCategory.get(cat)) {
    out += `\n### ${r.name}\n\n_Category: ${cat}, ${level(cat) === "off" ? "off by default" : `\`${level(cat)}\` by default`}. Since ${r.version}._\n\n${r.docs.replace(/^### /gm, "#### ")}\n`;
  }
}
process.stdout.write(out);
